{!REQUIRESCRIPT("/soap/ajax/60.0/connection.js")}
{!REQUIRESCRIPT("/support/console/60.0/integration.js")}

var caseId = "{!Case.Id}";
var contactId = "{!Case.ContactId}";
var department = "{!Case.Department__c}";
var slaTarget = "{!Case.AMFS_SLA_Target__c}";

if (!contactId || contactId === "") {
    alert("Maaf, Case tidak dapat ditutup karena Contact belum terisi.");
} else {
    var isConfirm = confirm("Apakah Anda yakin ingin menutup case ini?");

    if (isConfirm) {
        if (slaTarget == "OH" && (!department || department === "")) {
            alert("Harap Isi Department.");
        } else {
            // 1. Update Object Case
            var c = new sforce.SObject("Case");
            c.Id = caseId;
            c.Status = "Closed";
            var result = sforce.connection.update([c]);
            if (result[0].success) {
                // Close tab di Classic Console
                sforce.console.getEnclosingTabId(function(res) {
                    sforce.console.closeTab(res.id);
                });
            } else {
                alert("Gagal update case: " + result[0].errors[0].message);
            }
        }
    }
}
